// PreToolUse (Write|Edit|MultiEdit): Unity owns .meta files under client/Assets; a hand-written one breaks GUIDs.
import { readFileSync } from 'node:fs';

// Strip a BOM: PowerShell adds one when it pipes to a native process.
const input = JSON.parse(readFileSync(0, 'utf8').replace(/^\uFEFF/, ''));
const filePath = (input.tool_input?.file_path ?? '').replace(/\\/g, '/');
if (!/\/client\/Assets\/.+\.meta$/i.test(filePath)) process.exit(0);

process.stderr.write(
	'Blocked: .meta files under client/Assets are generated by Unity. Do not create or edit them by hand. ' +
	'Ask the user to focus the Unity Editor so it imports the new assets and writes the .meta files.\n');
process.exit(2);